// Fixture-driven test for
// xyh::scalefactor::btagging_strict::multi_wp_event_weight.
//
// A standalone (non-CROWN-generated) executable that drives the strict
// UParTAK4 fixed-multi-WP b-tag event-weight consumer against synthetic
// correctionlib fixtures (tests/fixtures/btag_sf_strict_{sf,eff}.json,
// generated by tests/fixtures/make_btag_sf_strict_fixtures.py).
//
// Cases:
//   (a) nominal weight reproduces a hand-computed value;
//   (b) efficiency <= 0 -> throws;
//   (c) non-monotonic efficiencies -> throws;
//   (d) comb-only variation (up_hf) changes b/c jets, leaves light central
//       (mixed-flavor event);
//   (e) unsupported variation key -> throws;
//   (f) jet passing the TIGHTEST WP (XXT) -> jet_w == SF(XXT), the eff-cancel
//       branch of the algebra;
//   (g) jet failing ALL WPs (score below the loosest, L) -> jet_w ==
//       (1 - SF(L)*eff(L)) / (1 - eff(L)), the untagged-probability branch;
//   (h) efficiency > 1 -> throws;
//   (i) a jet flavor outside {0, 4, 5} -> throws;
//   (j) b-jet below the calibrated pT range (30 GeV) -> SF of the first bin,
//       twice the deviation for a variation;
//   (k) ... with the efficiency at the jet pT.
// Cases (a)-(k) run with all five WPs {XXT, XT, T, M, L}; the v7 working
// points [T, M] (spec C14) and the K1 rule:
//   (l) [T, M]: a jet between M and T, above T, below M;
//   (m) K1: a negative numerator SF(M)eff(M) - SF(T)eff(T) sets the factor to
//       1 and is counted, also next to a jet with an ordinary factor;
//   (n) an empty, repeated, unknown or wrongly ordered WP list throws.
//
// The WP score thresholds are not passed in: the consumer reads them from the
// SF payload's UParTAK4_wp_values correction, which the fixture generator
// fills with (tightest -> loosest) {XXT: 0.9, XT: 0.7, T: 0.5, M: 0.3,
// L: 0.1} -- the thresholds every case below assumes.
//
// Run via: bash tests/cpp/run_btag_sf_test.sh (which regenerates the fixtures
// first; see that script for the compile command).

#include "btag_sf_strict.hxx"

#include "utility/CorrectionManager.hxx"

#include <ROOT/RDataFrame.hxx>
#include <ROOT/RVec.hxx>
#include <cmath>
#include <exception>
#include <functional>
#include <iostream>
#include <string>
#include <vector>

#ifndef BTAG_FIXTURE_SF
#define BTAG_FIXTURE_SF "tests/fixtures/btag_sf_strict_sf.json"
#endif
#ifndef BTAG_FIXTURE_EFF
#define BTAG_FIXTURE_EFF "tests/fixtures/btag_sf_strict_eff.json"
#endif

namespace {

int g_failures = 0;

// Lowest pT edge of the fixture's UParTAK4_comb pt binning
constexpr float kBcMinPt = 30.0f;

// Relative-tolerance float comparison for the hand-computed algebra.
bool approx_equal(double a, double b, double tol = 1e-6) {
    if (a == b) {
        return true;
    }
    double denom = std::abs(a) + std::abs(b);
    if (denom == 0.0) {
        return true;
    }
    return std::abs(a - b) / denom < tol;
}

void check(bool ok, const std::string &name) {
    std::cout << (ok ? "PASS " : "FAIL ") << name << std::endl;
    if (!ok) {
        ++g_failures;
    }
}

template <typename T>
ROOT::RVec<T> mkvec(const std::vector<T> &values) {
    ROOT::RVec<T> out;
    for (const auto &value : values) {
        out.push_back(value);
    }
    return out;
}

// All five fixture WPs, and the v7 working points, tightest first.
const std::vector<std::string> kAllWps = {"XXT", "XT", "T", "M", "L"};
const std::vector<std::string> kTM = {"T", "M"};

struct Result {
    double weight;
    int unity_count;
};

// Run the strict consumer on a single (possibly multi-jet) event and return
// the event weight and the count of factors set to 1. May throw (the strict
// consumer rejects degenerate input).
Result run_result(correctionManager::CorrectionManager &mgr,
                  const std::vector<float> &pt, const std::vector<float> &eta,
                  const std::vector<int> &flavor,
                  const std::vector<float> &score, const std::vector<int> &mask,
                  const std::string &eff_sample_type,
                  const std::string &variation_comb,
                  const std::string &variation_light,
                  const std::vector<std::string> &working_points = kAllWps) {
    ROOT::RDataFrame df(1);
    auto defined =
        df.Define("Jet_pt", [pt]() { return mkvec(pt); })
            .Define("Jet_eta", [eta]() { return mkvec(eta); })
            .Define("Jet_flavor", [flavor]() { return mkvec(flavor); })
            .Define("Jet_score", [score]() { return mkvec(score); })
            .Define("Jet_mask", [mask]() { return mkvec(mask); });
    ROOT::RDF::RNode node = defined;
    auto out = xyh::scalefactor::btagging_strict::multi_wp_event_weight(
        node, mgr, "btag_weight_upart", "btag_unity_jets_upart", "Jet_pt",
        "Jet_eta", "Jet_flavor", "Jet_score", "Jet_mask", BTAG_FIXTURE_SF,
        BTAG_FIXTURE_EFF, eff_sample_type, kBcMinPt, working_points,
        variation_comb, variation_light);
    auto weight = out.Take<double>("btag_weight_upart");
    auto count = out.Take<int>("btag_unity_jets_upart");
    return {weight.GetValue().at(0), count.GetValue().at(0)};
}

double run_weight(correctionManager::CorrectionManager &mgr,
                  const std::vector<float> &pt, const std::vector<float> &eta,
                  const std::vector<int> &flavor,
                  const std::vector<float> &score, const std::vector<int> &mask,
                  const std::string &eff_sample_type,
                  const std::string &variation_comb,
                  const std::string &variation_light,
                  const std::vector<std::string> &working_points = kAllWps) {
    return run_result(mgr, pt, eta, flavor, score, mask, eff_sample_type,
                      variation_comb, variation_light, working_points)
        .weight;
}

bool throws(const std::function<void()> &fn) {
    try {
        fn();
        return false;
    } catch (const std::exception &) {
        return true;
    }
}

} // namespace

int main() {
    correctionManager::CorrectionManager mgr;

    // ------------------------------------------------------------------
    // (a) Nominal weight reproduces a hand-computed value.
    //
    // A single b-jet (flavor 5) with score 0.4 passes WP M (0.4 >= 0.3) but
    // not WP T (0.4 < 0.5), so it lands in the M/T bin:
    //     jet_w = (SF(M)*eff(M) - SF(T)*eff(T)) / (eff(M) - eff(T))
    // With the fixture "valid" efficiencies (flavor 5): eff(M)=0.60, eff(T)=0.40
    // and central comb SFs (flavor 5): SF(M)=0.95, SF(T)=0.90:
    //     jet_w = (0.95*0.60 - 0.90*0.40) / (0.60 - 0.40)
    //           = (0.57 - 0.36) / 0.20 = 0.21 / 0.20 = 1.05
    // Kept in scope: case (d) reuses it as its b-only central reference.
    // ------------------------------------------------------------------
    const double w_bonly_cc = run_weight(mgr, {50.0f}, {1.0f}, {5}, {0.4f},
                                         {1}, "valid", "central", "central");
    check(approx_equal(w_bonly_cc, 1.05),
          "(a) nominal weight == hand-computed 1.05");

    // ------------------------------------------------------------------
    // (b) An efficiency <= 0 must throw (no silent 1.0 substitution). The
    // "zero" regime sets flavor-5 eff(M) = 0.
    // ------------------------------------------------------------------
    {
        bool did_throw = throws([&]() {
            run_weight(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {1}, "zero",
                       "central", "central");
        });
        check(did_throw, "(b) efficiency <= 0 throws");
    }

    // ------------------------------------------------------------------
    // (c) Non-monotonic efficiencies must throw. The "nonmono" regime sets
    // flavor-5 eff(M)=0.30 < eff(T)=0.50, so the M/T bin has a non-positive
    // denominator.
    // ------------------------------------------------------------------
    {
        bool did_throw = throws([&]() {
            run_weight(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {1}, "nonmono",
                       "central", "central");
        });
        check(did_throw, "(c) non-monotonic efficiency throws");
    }

    // ------------------------------------------------------------------
    // (d) A comb-only component (up_hf) changes b/c jets while leaving light
    // jets central. Mixed event: one b-jet (flavor 5, score 0.4) and one light
    // jet (flavor 0, score 0.15). Dispatch: variation_comb="up_hf",
    // variation_light="central".
    //
    // The event weight factorizes over jets, so comparing the mixed-event
    // (up_hf)/(central) ratio against the b-only one covers both halves of the
    // claim in two assertions: they can only agree if the light factor
    // cancels, i.e. is unchanged by the comb-only component, and the ratio
    // differing from 1 shows the b-jet really did change. The b-only central
    // weight is case (a)'s.
    // ------------------------------------------------------------------
    {
        double w_mixed_cc = run_weight(mgr, {50.0f, 60.0f}, {1.0f, 1.2f},
                                       {5, 0}, {0.4f, 0.15f}, {1, 1}, "valid",
                                       "central", "central");
        double w_mixed_uc = run_weight(mgr, {50.0f, 60.0f}, {1.0f, 1.2f},
                                       {5, 0}, {0.4f, 0.15f}, {1, 1}, "valid",
                                       "up_hf", "central");
        double w_bonly_uc = run_weight(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {1},
                                       "valid", "up_hf", "central");
        double ratio_mixed = w_mixed_uc / w_mixed_cc;
        double ratio_bonly = w_bonly_uc / w_bonly_cc;
        check(approx_equal(ratio_mixed, ratio_bonly),
              "(d) mixed-event variation ratio is entirely from the b-jet "
              "(light stays central)");
        check(!approx_equal(ratio_bonly, 1.0),
              "(d) comb-only component changes the b-jet weight");
    }

    // ------------------------------------------------------------------
    // (e) An unsupported variation key must throw (the fixture comb systematic
    // category has no default, so correctionlib raises; the consumer rethrows
    // with the jet kinematics).
    // ------------------------------------------------------------------
    {
        bool did_throw = throws([&]() {
            run_weight(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {1}, "valid",
                       "up_DOES_NOT_EXIST", "central");
        });
        check(did_throw, "(e) unsupported variation key throws");
    }

    // ------------------------------------------------------------------
    // (f) Jet passing the TIGHTEST WP (XXT). The payload thresholds
    // (tightest -> loosest) are {XXT:0.9, XT:0.7, T:0.5, M:0.3, L:0.1}; a
    // score of 0.95 >= 0.9 passes XXT, so `passed == 0` and the algebra
    // collapses to jet_w = (SF(XXT)*eff(XXT)) / eff(XXT) = SF(XXT) (the
    // efficiency cancels but is still evaluated/validated).
    // Flavor 5, "valid" regime, central comb SF/eff (from
    // make_btag_sf_strict_fixtures.py):
    //   SF(XXT) = COMB_BASE[5]["XXT"] + delta["central"] = 0.80 + 0 = 0.80
    //   eff(XXT) = EFF_VALID[5]["XXT"] = 0.10 (> 0, so no throw)
    //   jet_w = SF(XXT) = 0.80
    // ------------------------------------------------------------------
    {
        double w = run_weight(mgr, {50.0f}, {1.0f}, {5}, {0.95f}, {1}, "valid",
                              "central", "central");
        check(approx_equal(w, 0.80),
              "(f) tightest-WP pass reproduces hand-computed SF(XXT) == 0.80");
    }

    // ------------------------------------------------------------------
    // (g) Jet failing ALL WPs: score 0.05 < loosest threshold L (0.1), so
    // `passed == thresholds.size()` and the algebra uses the
    // untagged-probability branch:
    //     jet_w = (1 - SF(L)*eff(L)) / (1 - eff(L))
    // Flavor 5, "valid" regime, central comb SF/eff:
    //   SF(L) = COMB_BASE[5]["L"] + delta["central"] = 0.98 + 0 = 0.98
    //   eff(L) = EFF_VALID[5]["L"] = 0.80
    //   jet_w = (1 - 0.98*0.80) / (1 - 0.80)
    //         = (1 - 0.784) / 0.20 = 0.216 / 0.20 = 1.08
    // ------------------------------------------------------------------
    {
        double w = run_weight(mgr, {50.0f}, {1.0f}, {5}, {0.05f}, {1}, "valid",
                              "central", "central");
        check(approx_equal(w, 1.08),
              "(g) fails-all-WPs reproduces hand-computed "
              "(1-SF(L)*eff(L))/(1-eff(L)) == 1.08");
    }

    // ------------------------------------------------------------------
    // (h) An efficiency > 1 must throw as loudly as one <= 0. The "above_one"
    // regime sets flavor-5 eff(M) = 1.5.
    // ------------------------------------------------------------------
    {
        bool did_throw = throws([&]() {
            run_weight(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {1}, "above_one",
                       "central", "central");
        });
        check(did_throw, "(h) efficiency > 1 throws");
    }

    // ------------------------------------------------------------------
    // (i) A hadron flavor outside {0, 4, 5} has no per-flavor correction to
    // dispatch to, so it must throw rather than be silently skipped.
    // ------------------------------------------------------------------
    {
        bool did_throw = throws([&]() {
            run_weight(mgr, {50.0f}, {1.0f}, {3}, {0.4f}, {1}, "valid",
                       "central", "central");
        });
        check(did_throw, "(i) unknown jet flavor throws");
    }

    // ------------------------------------------------------------------
    // (j) A b-jet below the calibrated pT range takes the SF of the first bin
    // (30-100 GeV), not the payload's flow (the last bin, +0.05), with twice
    // the deviation of a variation. pt 25 GeV, score 0.4 (M/T bin), "valid"
    // efficiencies below 30 GeV: eff(M) = 0.30, eff(T) = 0.20.
    //   central: (0.95*0.30 - 0.90*0.20) / 0.10 = 1.05
    //   up_hf:   SF + 2*0.10 -> (1.15*0.30 - 1.10*0.20) / 0.10 = 1.25
    // (the flow would give 1.10 and 1.20, an undoubled up_hf 1.15)
    // ------------------------------------------------------------------
    {
        double w_central = run_weight(mgr, {25.0f}, {1.0f}, {5}, {0.4f}, {1},
                                      "valid", "central", "central");
        double w_up = run_weight(mgr, {25.0f}, {1.0f}, {5}, {0.4f}, {1},
                                 "valid", "up_hf", "central");
        check(approx_equal(w_central, 1.05),
              "(j) b-jet below 30 GeV takes the first-bin SF");
        check(approx_equal(w_up, 1.25),
              "(j) b-jet below 30 GeV doubles the variation");
    }

    // ------------------------------------------------------------------
    // (k) ... while its efficiency stays at the jet pT. Fails all WPs
    // (score 0.05), pt 25 GeV: eff(L) = 0.40, SF(L) = 0.98:
    //   (1 - 0.98*0.40) / (1 - 0.40) = 0.608 / 0.60
    // (the efficiency at 30 GeV would give 1.08, the flow SF of 1.03 0.98)
    // ------------------------------------------------------------------
    {
        double w = run_weight(mgr, {25.0f}, {1.0f}, {5}, {0.05f}, {1}, "valid",
                              "central", "central");
        check(approx_equal(w, 0.608 / 0.60),
              "(k) b-jet below 30 GeV keeps the efficiency at its pT");
    }

    // ------------------------------------------------------------------
    // (l) The v7 working points [T, M]. A b-jet (flavor 5, valid regime, pt
    // 50) with score 0.4 lies between M and T as with five WPs:
    //   (0.95*0.60 - 0.90*0.40) / (0.60 - 0.40) = 1.05;
    // score 0.6 passes T, the tightest WP of the list (with five WPs it would
    // be the T/XT bin): SF(T) = 0.90;
    // score 0.2 fails M, the loosest WP of the list (five WPs: the L/M bin):
    //   (1 - 0.95*0.60) / (1 - 0.60) = 0.43 / 0.40 = 1.075.
    // None of them counts a factor set to 1.
    // ------------------------------------------------------------------
    {
        const auto between = run_result(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {1},
                                        "valid", "central", "central", kTM);
        const auto tight = run_result(mgr, {50.0f}, {1.0f}, {5}, {0.6f}, {1},
                                      "valid", "central", "central", kTM);
        const auto untagged = run_result(mgr, {50.0f}, {1.0f}, {5}, {0.2f},
                                         {1}, "valid", "central", "central",
                                         kTM);
        check(approx_equal(between.weight, 1.05) && between.unity_count == 0,
              "(l) [T,M]: between M and T == 1.05");
        check(approx_equal(tight.weight, 0.90) && tight.unity_count == 0,
              "(l) [T,M]: above T == SF(T) 0.90");
        check(approx_equal(untagged.weight, 0.43 / 0.40) &&
                  untagged.unity_count == 0,
              "(l) [T,M]: below M == (1-SF(M)eff(M))/(1-eff(M)) 1.075");
    }

    // ------------------------------------------------------------------
    // (m) K1: up_k1 raises SF(T) of b/c jets to 1.50, so the M/T numerator of
    // a b-jet with score 0.4 is 0.95*0.60 - 1.50*0.40 = -0.03 < 0: the factor
    // is 1 and counted. A light jet (score 0.15, fails M) next to it keeps its
    // factor (1 - 0.96*0.05) / (1 - 0.05); two such b-jets count 2; a b-jet
    // above T takes SF(T) = 1.50 and counts nothing.
    // ------------------------------------------------------------------
    {
        const auto single = run_result(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {1},
                                       "valid", "up_k1", "central", kTM);
        check(approx_equal(single.weight, 1.0) && single.unity_count == 1,
              "(m) K1: negative numerator gives factor 1, counted once");
        const auto mixed = run_result(mgr, {50.0f, 60.0f}, {1.0f, 1.2f}, {5, 0},
                                      {0.4f, 0.15f}, {1, 1}, "valid", "up_k1",
                                      "central", kTM);
        check(approx_equal(mixed.weight, (1.0 - 0.96 * 0.05) / (1.0 - 0.05)) &&
                  mixed.unity_count == 1,
              "(m) K1: the other jets keep their factors");
        const auto two = run_result(mgr, {50.0f, 70.0f}, {1.0f, -0.5f}, {5, 5},
                                    {0.4f, 0.45f}, {1, 1}, "valid", "up_k1",
                                    "central", kTM);
        check(approx_equal(two.weight, 1.0) && two.unity_count == 2,
              "(m) K1: two negative numerators count 2");
        const auto tight = run_result(mgr, {50.0f}, {1.0f}, {5}, {0.6f}, {1},
                                      "valid", "up_k1", "central", kTM);
        check(approx_equal(tight.weight, 1.50) && tight.unity_count == 0,
              "(m) K1: a jet above T is not affected");
        const auto central = run_result(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {1},
                                        "valid", "central", "central", kTM);
        check(central.unity_count == 0,
              "(m) K1: central SFs count no factor set to 1");
        const auto masked = run_result(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {0},
                                       "valid", "up_k1", "central", kTM);
        check(approx_equal(masked.weight, 1.0) && masked.unity_count == 0,
              "(m) K1: a masked jet is not counted");
    }

    // ------------------------------------------------------------------
    // (n) The working-point list must be non-empty, without repetitions, of
    // payload WPs, tightest first (strictly decreasing thresholds).
    // ------------------------------------------------------------------
    for (const auto &wps : std::vector<std::vector<std::string>>{
             {}, {"T", "T"}, {"T", "Q"}, {"M", "T"}}) {
        std::string name = "(n) WP list {";
        for (const auto &wp : wps) {
            name += wp + " ";
        }
        name += "} throws";
        check(throws([&]() {
                  run_weight(mgr, {50.0f}, {1.0f}, {5}, {0.4f}, {1}, "valid",
                             "central", "central", wps);
              }),
              name);
    }

    if (g_failures > 0) {
        std::cerr << g_failures << " case(s) FAILED" << std::endl;
        return 1;
    }
    std::cout << "All strict UParTAK4 b-tag cases PASSED." << std::endl;
    return 0;
}
